  /** Change a draft's amount in its row, keeping its date, note and the claim it corrects: the claim form's save,
   *  under the same rules. */
  protected saveInline(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const amount = (this.inlineAmounts()[c.id] ?? '').trim();
    const refuse = (message: string) => this.claimError.set({ id: c.id, message });
    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
      refuse('Type an amount with up to two decimals; a negative one is a correction.');
      return;
    }
    const correction = amount.startsWith('-');
    if (correction && c.corrects === null) {
      refuse('A negative amount is a correction: use the claim form to name the settled claim it corrects.');
      return;
    }
    if (!correction && c.corrects !== null) {
      refuse('Only a negative amount (a correction) names a claim it corrects.');
      return;
    }
    if (c.status !== 'DRAFT') {
      refuse(`A ${c.status} claim cannot be edited. Void it and add a new one.`);
      return;
    }
    if (c.lockedBy !== null && c.lockedBy !== this.session.user()) {
      refuse(`${c.lockedBy} is editing this claim, so it is locked until they are done.`);
      return;
    }
    this.api.update(sheet.id, c.id, { amount, date: c.date, note: c.note, corrects: c.corrects, ref: c.ref, tags: c.tags.join(',') }).subscribe({
      next: (saved) => {
        this.inlineAmounts.update((amounts) => ({ ...amounts, [c.id]: '' }));
        // The save released this user's lock, so an editor they had open on it is closed.
        if (this.editingId() === c.id) this.reset();
        this.saved.emit(saved);
      },
      error: (err: unknown) => refuse(
        err instanceof HttpErrorResponse && err.status === 403
          ? 'Your role may not edit a claim.'
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 422
              ? 'That claim is dated after the person retired.'
              : err instanceof HttpErrorResponse && err.status === 409
                ? 'Only a draft claim can be edited, and not while another user is editing it.'
                : 'Could not save that amount.',
      ),
    });
  }

